From 1649782106145b79e8639de2623d666087004b01 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:32:14 +0100
Subject: [PATCH] applets/weather: don't ask about invalid certificates

When a weather provider's certificate failed to verify, every refresh
popped up KIO's modal certificate dialog over the desktop. The providers'
requests now skip that dialog and fail, so the widget shows its error.

BUG: 446328
---
 applets/weather/ions/bbcukmet/ion_bbcukmet.cpp     | 1 +
 applets/weather/ions/dwd/ion_dwd.cpp               | 1 +
 applets/weather/ions/envcan/ion_envcan.cpp         | 3 +++
 applets/weather/ions/noaa/ion_noaa.cpp             | 1 +
 applets/weather/ions/open-meteo/ion_open_meteo.cpp | 2 ++
 5 files changed, 8 insertions(+)

diff --git a/applets/weather/ions/bbcukmet/ion_bbcukmet.cpp b/applets/weather/ions/bbcukmet/ion_bbcukmet.cpp
index 2773dbb2f..a64abdcbf 100644
--- a/applets/weather/ions/bbcukmet/ion_bbcukmet.cpp
+++ b/applets/weather/ions/bbcukmet/ion_bbcukmet.cpp
@@ -285,6 +285,7 @@ KJob *UKMETIon::requestAPIJob(const QUrl &url, QByteArray &result)
 {
     KIO::TransferJob *getJob = KIO::get(url, KIO::Reload, KIO::HideProgressInfo);
     getJob->addMetaData(u"cookies"_s, u"none"_s);
+    getJob->addMetaData(u"ssl_no_ui"_s, u"true"_s);

     qCDebug(WEATHER::ION::BBCUKMET) << "Requesting URL:" << url;

