             m_xmlSetup = std::make_shared<QXmlStreamReader>();
             connect(getJob, &KIO::TransferJob::data, this, &EnvCanadaIon::places_slotDataArrived);
@@ -514,6 +516,7 @@ void EnvCanadaIon::getWeatherData()
